package dev.obiente.nextcloudnative.app

import kotlin.random.Random

/** Whose address book this is, for what the user may do with it. */
internal enum class AddressBookOwnership { Own, SharedWithMe, System }

internal data class ManagedAddressBook(
    val href: String,
    val displayName: String,
    val ownership: AddressBookOwnership,
    val ownerName: String?,
    val writable: Boolean,
)

/**
 * Address books in the user's CardDAV home with their owner, read from the same properties the
 * calendar list uses. Address books generated by the server, such as the system address book of
 * all users, are listed as [AddressBookOwnership.System] and cannot be changed.
 */
internal fun parseManagedAddressBooks(response: NextcloudApiResponse, userId: String): List<ManagedAddressBook> {
    require(response.status in 200..299) { "Address books could not be read (HTTP ${response.status})." }
    return response.body.decodeToString().xmlElements("response").mapNotNull { block ->
        val href = block.xmlDirectChildText("href")?.decodeXmlEntities()?.trim()?.takeIf { it.endsWith('/') } ?: return@mapNotNull null
        if (!block.containsXmlElement("addressbook")) return@mapNotNull null
        val owner = block.xmlText("owner-principal")?.decodeXmlEntities()?.trim()?.trimEnd('/')
        val ownerUser = owner?.takeIf { it.startsWith("principals/users/") }?.substringAfterLast('/')?.decodePercentEncoding()
        val privileges = block.xmlElements("privilege").flatMap { it.xmlElementNames() }
        val segment = href.trimEnd('/').substringAfterLast('/')
        ManagedAddressBook(
            href = href.requireSafeDavHref(),
            displayName = block.xmlText("displayname")?.decodeXmlEntities()?.trim()?.takeIf(String::isNotBlank)
                ?: segment.decodePercentEncoding(),
            ownership = when {
                segment.startsWith("z-server-generated--") || segment.startsWith("z-app-generated--") ||
                    owner?.startsWith("principals/system/") == true -> AddressBookOwnership.System
                ownerUser != null && ownerUser != userId -> AddressBookOwnership.SharedWithMe
                else -> AddressBookOwnership.Own
            },
            ownerName = block.xmlText("owner-displayname")?.decodeXmlEntities()?.trim()?.takeIf(String::isNotBlank) ?: ownerUser,
            writable = privileges.any { it == "write" || it == "write-content" || it == "all" },
        )
    }.distinctBy(ManagedAddressBook::href)
}

/** RFC 6352 extended MKCOL for a new address book. */
internal fun addressBookCreateRequest(href: String, name: String): GroupwareDavRequest = addressBookRequest(
    "MKCOL", href,
    """<d:mkcol xmlns:d="DAV:" xmlns:card="urn:ietf:params:xml:ns:carddav"><d:set><d:prop>""" +
        "<d:resourcetype><d:collection/><card:addressbook/></d:resourcetype>" +
        "<d:displayname>${requireAddressBookName(name).escapeDavXml()}</d:displayname></d:prop></d:set></d:mkcol>",
)

internal fun addressBookRenameRequest(href: String, name: String): GroupwareDavRequest = addressBookRequest(
    "PROPPATCH", href,
    """<d:propertyupdate xmlns:d="DAV:"><d:set><d:prop>""" +
        "<d:displayname>${requireAddressBookName(name).escapeDavXml()}</d:displayname></d:prop></d:set></d:propertyupdate>",
)

/** Deletes an own address book with every contact in it, or removes one shared with the user. */
internal fun addressBookDeleteRequest(href: String): GroupwareDavRequest = GroupwareDavRequest(
    method = "DELETE",
    relativePath = requireAddressBookHref(href),
    maximumResponseBytes = ADDRESS_BOOK_RESPONSE_BYTES,
)

internal fun newAddressBookHref(homeHref: String, name: String, random: Random = Random.Default): String {
    val slug = name.lowercase().map { if (it in 'a'..'z' || it in '0'..'9') it else '-' }.joinToString("")
        .replace(Regex("-+"), "-").trim('-').take(40).trim('-').ifBlank { "contacts" }
    val suffix = (1..6).map { ADDRESS_BOOK_SLUG_ALPHABET[random.nextInt(ADDRESS_BOOK_SLUG_ALPHABET.length)] }.joinToString("")
    return requireAddressBookHref("${homeHref.requireSafeDavHref().trimEnd('/')}/$slug-$suffix/")
}

internal fun addressBookNameMessage(name: String): String? = when {
    name.isBlank() -> "Enter a name."
    name.trim().length > MAX_ADDRESS_BOOK_NAME || name.any(Char::isISOControl) -> "Use a shorter name without special characters."
    else -> null
}

private fun requireAddressBookName(name: String): String {
    require(addressBookNameMessage(name) == null) { "The address book name is invalid." }
    return name.trim()
}

private fun addressBookRequest(method: String, href: String, body: String) = GroupwareDavRequest(
    method = method,
    relativePath = requireAddressBookHref(href),
    contentType = "application/xml; charset=utf-8",
    body = """<?xml version="1.0" encoding="UTF-8"?>$body""".encodeToByteArray(),
    maximumResponseBytes = ADDRESS_BOOK_RESPONSE_BYTES,
)

private fun requireAddressBookHref(href: String): String {
    href.requireSafeDavHref()
    val rest = href.removePrefix(ADDRESS_BOOK_HOME_PREFIX).trimEnd('/')
    require(href.startsWith(ADDRESS_BOOK_HOME_PREFIX) && href.endsWith('/') && rest.count { it == '/' } == 1 &&
        !rest.substringAfter('/').startsWith("z-")) {
        "An address book change must target an address book in an address book home."
    }
    return href
}

private const val ADDRESS_BOOK_HOME_PREFIX = "/remote.php/dav/addressbooks/users/"
private const val ADDRESS_BOOK_SLUG_ALPHABET = "abcdefghijklmnopqrstuvwxyz0123456789"
private const val MAX_ADDRESS_BOOK_NAME = 200
private const val ADDRESS_BOOK_RESPONSE_BYTES = 256L * 1024L
